import { useTranslation } from "react-i18next";
import { ArrowUpDown } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { formatQuantityLocalized } from "@/lib/i18nHelpers";
import type { StockMove } from "@/modules/maker/types/maker";

interface ProductionStockMovesTableProps {
  stockMoves: StockMove[];
}

/** Read-only table of stock moves generated by a production order. */
export function ProductionStockMovesTable({
  stockMoves,
}: ProductionStockMovesTableProps) {
  const { t } = useTranslation("maker");

  if (stockMoves.length === 0) return null;

  return (
    <div className="space-y-3">
      <h2 className="text-xs uppercase tracking-widest text-on-muted font-medium px-1 flex items-center gap-1">
        <ArrowUpDown size={12} />
        {t("detail.stockMoves")}
      </h2>
      <Card className="p-2">
        <div className="divide-y divide-border">
          <div className="grid grid-cols-[auto_1fr_auto] gap-4 p-3 text-xs uppercase tracking-widest text-on-muted font-medium">
            <span>{t("detail.stockMove.dir")}</span>
            <span>{t("detail.stockMove.product")}</span>
            <span className="text-right">{t("detail.stockMove.qty")}</span>
          </div>
          {stockMoves.map((move) => {
            // A side without an id never had a location to name: the
            // consumption goes from a shelf into the run, the receipt
            // arrives out of it. A side with an id whose name is gone
            // still answers — as the label, not the identifier.
            const fromName = move.from_location_id
              ? (move.from_location_name ?? t("detail.line.unknownLocation"))
              : null;
            const toName = move.to_location_id
              ? (move.to_location_name ?? t("detail.line.unknownLocation"))
              : null;
            const trace =
              fromName && toName
                ? `${fromName} → ${toName}`
                : (fromName ?? toName);
            return (
              <div
                key={move.id}
                className="grid grid-cols-[auto_1fr_auto] gap-4 p-3 items-center text-sm"
              >
                <span className="text-lg">
                  {move.from_location_id ? "↓" : "↑"}
                </span>
                {/* Names, not truncated identifiers: a reader cannot tell two
                    products apart by the first twelve characters of a UUID.
                    The id stays reachable as a tooltip. */}
                <div className="min-w-0">
                  <div
                    className="text-sm text-on truncate"
                    title={move.product_template_id}
                  >
                    {move.product_template_name ??
                      t("detail.stockMove.unknownProduct")}
                  </div>
                  {move.lot_id && (
                    <div
                      className="text-xs text-on-muted mt-0.5 truncate"
                      title={move.lot_id}
                    >
                      {t("detail.stockMove.lot")}: {move.lot_code ?? "—"}
                    </div>
                  )}
                  {/* The same arrow the ingredients table above writes —
                      "← Cold Storage" — so one run reads one vocabulary. */}
                  {trace && (
                    <div
                      className="text-xs text-on-muted mt-0.5 truncate"
                      title={[move.from_location_id, move.to_location_id]
                        .filter(Boolean)
                        .join(" → ")}
                    >
                      {fromName && toName
                        ? trace
                        : fromName
                          ? `← ${trace}`
                          : `→ ${trace}`}
                    </div>
                  )}
                </div>
                {/* The same screen writes "200 ml" and "4 kg" in the
                    consumption table; the moves table said "200" and "4". */}
                <div className="text-right font-medium">
                  {formatQuantityLocalized(t, move.quantity, move.uom_symbol)}
                </div>
              </div>
            );
          })}
        </div>
      </Card>
    </div>
  );
}
